int main() {
    int x, y, z;
    while (cin >> x >> y >> z) {
        if (x > y) {
            cout << (x <= y + z ? '?' : '+') << '\n';
        } else if (x < y) {
            cout << (x + z >= y ? '?' : '-') << '\n';
        } else {
            cout << (z == 0 ? '0' : '?') << '\n';
        }
    }
    return 0;
}

